"""Shared helpers for importers: stable ids, bullet splitting, merging into a profile.

Importers never invent anything: they only restructure text the user already wrote. Their
output is a DRAFT the user reviews, which is why every written file starts with a warning.
"""
from __future__ import annotations

import re
import unicodedata
from pathlib import Path

from jac.profile import Bullet, Fact, FactKind, Profile, dump_profile, load_profile

DRAFT_HEADER = (
    "# DRAFT generated by an importer. Read every line, fix mistakes, delete what is not true.\n"
    "# The tool can only reuse facts that are in this file.\n"
)
_SENTENCE_SPLIT = re.compile(r"(?<=[.!?])\s+(?=[A-Z])")


def slug(text: str, limit: int = 28) -> str:
    """Lowercase ascii slug for ids."""
    ascii_text = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode()
    return re.sub(r"[^a-z0-9]+", "-", ascii_text.lower()).strip("-")[:limit].strip("-") or "item"


class IdFactory:
    """Hands out unique fact ids within one draft."""

    _PREFIX = {"experience": "exp", "project": "proj", "publication": "pub", "education": "edu"}

    def __init__(self) -> None:
        self._used: set[str] = set()

    def fact_id(self, kind: FactKind, title: str) -> str:
        base = f"{self._PREFIX[kind]}-{slug(title)}"
        ident, n = base, 2
        while ident in self._used:
            ident, n = f"{base}-{n}", n + 1
        self._used.add(ident)
        return ident


def make_fact(ids: IdFactory, kind: FactKind, title: str, bullets: list[str], **fields: str | list[str]) -> Fact:
    """Build a Fact with generated ids; empty bullet texts are skipped."""
    fact_id = ids.fact_id(kind, title)
    clean = [b.strip() for b in bullets if b and b.strip()]
    return Fact(
        id=fact_id,
        kind=kind,
        title=title.strip(),
        bullets=[Bullet(id=f"{fact_id}.b{i}", text=t) for i, t in enumerate(clean, 1)],
        **fields,  # type: ignore[arg-type]
    )


def split_sentences(text: str) -> list[str]:
    """Split running prose into sentence bullets."""
    return [s.strip() for s in _SENTENCE_SPLIT.split(" ".join(text.split())) if s.strip()]


def split_description(text: str) -> list[str]:
    """Split a free-text description on bullet marks and line breaks, else on sentences."""
    lines = [re.sub(r"^[\s•\-–*·]+", "", line).strip() for line in text.replace("\r", "").splitlines()]
    lines = [line for line in lines if line]
    return lines if len(lines) > 1 else split_sentences(text)


def merge_into_profile(draft: Profile, path: Path) -> Profile:
    """Write a draft into profile.yaml, keeping the constraints and never_claim already there."""
    base = load_profile(path) if path.exists() else Profile()
    identity = base.identity.model_copy()
    for name, value in draft.identity.model_dump().items():
        if value and not getattr(identity, name):
            setattr(identity, name, value)
    identity.links = {**draft.identity.links, **identity.links}
    merged = base.model_copy(
        update={
            "identity": identity,
            "summary": draft.summary or base.summary,
            "facts": draft.facts or base.facts,
            "skills": draft.skills or base.skills,
        }
    )
    merged = Profile.model_validate(merged.model_dump())
    dump_profile(merged, path, header=DRAFT_HEADER)
    return merged
